describe('Dynamic Loading Test', () => {
    beforeEach(() => {
        cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    });

    it('should reveal hidden content after loading', () => {
        cy.get('#finish').should('not.be.visible');
        cy.get('#start button').click();
        cy.get('#loading').should('be.visible');
        cy.get('#loading').should('not.exist');
        cy.get('#finish').should('be.visible').and('contain', 'Hello World!');
    });

    it('should handle loading timeout gracefully', () => {
        cy.get('#finish').should('not.be.visible');
        cy.get('#start button').click();
        cy.get('#loading').should('be.visible');
        cy.wait(11000); // wait longer than the expected load time
        cy.get('#finish').should('not.be.visible'); // ensure it is still not visible
    });
});
